from pathlib import Path
s=Path('archive/browser/browser-vikings70.js').read_text(encoding='utf-8').replace('3017','3018').replace('clockPhoto70','clockPhoto71').replace('vikings70-','clockwork71-')
old="await climb(2,1450,1260);await climb(2,1800,920);await move(2,1690);await climb(1,1320,650);await climb(1,1450,1260);await climb(1,1800,920);await move(1,1770);await photo('crew-board');"
new="await move(2,1400);await tick({overhead:true});await climb(1,1320,650);await climb(1,1400,570);await tick({right:true});await wait(()=>read().heroes[1].support===2,()=>({}),3,'second board');await photo('second-board');select(2);await wait(()=>read().heroes[2].x>1710,()=>({right:true}),6,'second glide');await photo('second-glide');await wait(()=>read().heroes[2].ground,()=>({}),6,'second land');await move(2,1690);await move(1,1770);await photo('crew-board');"
assert old in s;s=s.replace(old,new)
s=s.replace("await climb(2,420,380);await move(2,450);await tick({overhead:true});", "await climb(2,420,380);await climb(2,450,300);await photo('tower-before');await tick({interact:true});await tick({},.35);await photo('tower-working');await wait(()=>read().machine.catchWound,()=>({}),3,'regulator wound');await photo('tower-wound');await climb(2,450,380);await tick({right:true});await tick({},.2);await tick({overhead:true});")
s=s.replace("await photo('start');if(!recovery)await board();", "await photo('start');if(!recovery){await board();select(0);await wait(()=>read().heroes[0].x<521,()=>({left:true}),3,'cup left');await photo('cup-left');await wait(()=>read().heroes[0].x>599,()=>({right:true}),4,'cup right');await photo('cup-right');await move(0,560);}")
s=s.replace("['shield-board','catch-compressed'","['tower-before','tower-working','tower-wound','cup-left','cup-right','release-inset','released','start','second-board','second-glide','pin-breaking','shield-board','catch-compressed'")
s=s.replace("await photo('pin-breaking');","await photo('pin-breaking');if(!read().view.release||!read().view.split)throw Error('Erik release inset missing');")
s=s.replace("select(0);await photo('released');","await photo('release-inset');if(!read().view.release||read().machine.wheel.occupied)throw Error('Released runner inset missing');select(0);await photo('released');")
s=s.replace("await page.locator('#play-clockwork').click();", "await page.locator('#play-clockwork').click();if((await page.locator('#zoom').textContent()).startsWith('1'))await page.locator('#zoom').click();")
Path('archive/browser/browser-clockwork71.js').write_text(s,encoding='utf-8')
